"""Validate and export invoice JSON with total for the billing API (pydantic 1.10)."""
from datetime import datetime, timezone
from decimal import Decimal, ROUND_DOWN
from typing import List, Union

from pydantic import BaseModel, validator, ValidationError, root_validator

# Reuse Line and Invoice from json_export with slight extension for quantity >=1 and unit_price >=0
# We redefine here to add stricter validation as requested.

def _utc_z(dt: datetime) -> str:
    return dt.strftime("%Y-%m-%dT%H:%M:%SZ")


class Line(BaseModel):
    sku: str
    quantity: int
    unit_price: Decimal

    @validator("quantity")
    def quantity_must_be_at_least_1(cls, v):
        if v < 1:
            raise ValueError("quantity must be >= 1")
        return v

    @validator("unit_price", pre=True)
    def unit_price_must_be_decimal_and_nonnegative(cls, v):
        # Accept str/int/float, convert to Decimal
        try:
            dec = Decimal(v)
        except Exception:
            raise ValueError("unit_price must be a decimal number")
        if dec < 0:
            raise ValueError("unit_price must be >= 0")
        # Quantize to 2 decimal places without rounding up
        dec = dec.quantize(Decimal("0.01"), rounding=ROUND_DOWN)
        return dec


class Invoice(BaseModel):
    number: str
    issued_at: datetime
    lines: List[Line]

    @validator("issued_at", pre=True)
    def parse_issued_at(cls, v):
        if isinstance(v, datetime):
            dt = v
        elif isinstance(v, str):
            try:
                dt = datetime.fromisoformat(v)
            except Exception:
                raise ValueError("issued_at must be a valid ISO 8601 datetime string or datetime")
        else:
            raise ValueError("issued_at must be a datetime or ISO 8601 string")
        # If naive, treat as UTC
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        else:
            dt = dt.astimezone(timezone.utc)
        # Remove microseconds for second precision
        dt = dt.replace(microsecond=0)
        return dt

    @root_validator
    def check_lines_not_empty(cls, values):
        lines = values.get("lines")
        if not lines:
            raise ValueError("lines must not be empty")
        return values


def export_invoice(data: dict) -> str:
    """
    Validate invoice data and return JSON text for billing API with total included.

    Input:
      - number (str)
      - issued_at (ISO 8601 string or datetime; naive treated as UTC)
      - lines: list of dicts with sku (str), quantity (int >=1), unit_price (decimal >=0 as str/int/float)

    Output JSON keys:
      - number (str)
      - issued_at (str, formatted YYYY-MM-DDTHH:MM:SSZ UTC)
      - lines: list of dicts with sku, quantity, unit_price (string with exactly two decimals)
      - total: string with exactly two decimals (sum of quantity * unit_price)

    Raises ValueError on invalid input.
    """
    try:
        invoice = Invoice.parse_obj(data)
    except ValidationError as e:
        raise ValueError(e)

    # Prepare output dict
    out = {
        "number": invoice.number,
        "issued_at": _utc_z(invoice.issued_at),
        "lines": [],
    }

    total = Decimal("0.00")
    for line in invoice.lines:
        # Format unit_price as string with exactly two decimals
        unit_price_str = f"{line.unit_price:.2f}"
        out["lines"].append({
            "sku": line.sku,
            "quantity": line.quantity,
            "unit_price": unit_price_str,
        })
        total += line.unit_price * line.quantity

    # Format total as string with two decimals
    total_str = f"{total.quantize(Decimal('0.01')):.2f}"
    out["total"] = total_str

    import json
    return json.dumps(out, separators=(",", ":"))

from typing import List, Optional

from pydantic import BaseModel, validator


class ImportProfile(BaseModel):
    user_id: int
    display_name: str
    bio: Optional[str] = None
    zip_code: str

    @validator("display_name")
    def clean_display_name(cls, value):
        value = " ".join(value.split())
        if not value:
            raise ValueError("display_name must not be blank")
        return value

    @validator("zip_code", pre=True)
    def zip_code_to_str(cls, value):
        return str(value)


def import_profiles(rows: list) -> list:
    valid_profiles = []
    for row in rows:
        try:
            profile = ImportProfile.parse_obj(row)
        except Exception:
            continue
        valid_profiles.append(profile.dict())
    return valid_profiles

"""Invoice JSON export for the billing API (pydantic 2.0)."""
from datetime import datetime, timezone
from decimal import Decimal, ROUND_HALF_UP
from typing import List, Union

from pydantic import BaseModel, Field, field_validator, model_validator


class Line(BaseModel):
    sku: str
    quantity: int = Field(..., ge=1)
    unit_price: Decimal = Field(..., ge=0)

    @field_validator("unit_price", mode="before")
    @classmethod
    def coerce_unit_price(cls, v):
        # Accept str, int, float and convert to Decimal
        try:
            return Decimal(str(v))
        except Exception:
            raise ValueError("unit_price must be a decimal number >= 0")

    def unit_price_str(self) -> str:
        # Format unit_price as string with exactly two decimals
        return f"{self.unit_price.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)}"


class Invoice(BaseModel):
    number: str
    issued_at: Union[datetime, str]
    lines: List[Line]

    @model_validator(mode="before")
    @classmethod
    def validate_issued_at(cls, values):
        issued_at = values.get("issued_at")
        if issued_at is None:
            raise ValueError("issued_at is required")
        if isinstance(issued_at, str):
            # Parse ISO 8601 string
            try:
                dt = datetime.fromisoformat(issued_at)
            except Exception:
                raise ValueError("issued_at must be ISO 8601 datetime string or datetime object")
            values["issued_at"] = dt
        elif not isinstance(issued_at, datetime):
            raise ValueError("issued_at must be ISO 8601 datetime string or datetime object")
        return values

    @model_validator(mode="after")
    def normalize_issued_at(self):
        dt = self.issued_at
        # Convert naive datetime to UTC
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        else:
            dt = dt.astimezone(timezone.utc)
        object.__setattr__(self, "issued_at", dt)
        return self


def export_invoice(data: dict) -> str:
    """Validate invoice data and return JSON text for the billing API.

    Raises ValueError for invalid input.
    """
    invoice = Invoice.model_validate(data)

    # Compute total as Decimal
    total = Decimal("0")
    for line in invoice.lines:
        total += line.unit_price * line.quantity

    # Format issued_at as "YYYY-MM-DDTHH:MM:SSZ"
    issued_at_str = invoice.issued_at.strftime("%Y-%m-%dT%H:%M:%SZ")

    # Prepare lines with formatted unit_price strings
    lines_out = []
    for line in invoice.lines:
        lines_out.append({
            "sku": line.sku,
            "quantity": line.quantity,
            "unit_price": line.unit_price_str(),
        })

    # Format total with two decimals
    total_str = f"{total.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)}"

    # Build output dict
    out = {
        "number": invoice.number,
        "issued_at": issued_at_str,
        "lines": lines_out,
        "total": total_str,
    }

    # Use pydantic BaseModel json encoder for consistent JSON output
    # But since we want a string output, use standard json.dumps
    # We can import json here:
    import json
    return json.dumps(out, separators=(",", ":"))

"""Validate a sign-up payload with username, email, phone, password and password_confirm."""
import re
from pydantic import BaseModel, Field, model_validator, field_validator, ValidationError


class SignupPayload(BaseModel):
    username: str = Field(..., pattern=r"^[a-z0-9_]{3,20}$")
    email: str
    phone: str
    password: str = Field(..., min_length=8)
    password_confirm: str

    @model_validator(mode='before')
    @classmethod
    def passwords_match(cls, values):
        password = values.get("password")
        confirm = values.get("password_confirm")
        if password is not None and confirm is not None and password != confirm:
            raise ValueError("passwords do not match")
        return values

    @field_validator("email")
    @classmethod
    def validate_email(cls, value: str) -> str:
        if "@" not in value:
            raise ValueError("email must contain '@'")
        return value.strip().lower()

    @field_validator("phone")
    @classmethod
    def validate_phone(cls, value: str) -> str:
        if not isinstance(value, str):
            raise TypeError("phone must be a string")
        compact = re.sub(r"[\s.\-()]", "", value)
        if not re.fullmatch(r"\+\d{8,15}", compact):
            raise ValueError("invalid phone number")
        return compact


def validate_signup(data: dict) -> dict:
    """Validate a sign-up payload dict and return dict with username, email, phone (compact).
    Raise pydantic.ValidationError (ValueError) if invalid."""
    validated = SignupPayload.model_validate(data)
    return {
        "username": validated.username,
        "email": validated.email,
        "phone": validated.phone,
    }
